#include <iostream>
#include <array>
template <class T, size_t N>
bool operator>=(const std::array<T,N>& x, const std::array<T,N>& y) {
  for (size_t i = 0; i < N; ++i) {
    if (x[i] < y[i]) return false;
  }
  return true;
}
int main() {
  std::array<int, 4> a = {1, 2, 3, 4};
  std::array<int, 4> b = {1, 2, 3, 5};
  std::cout << (a >= b) << std::endl; // Output: 0
  std::array<int, 4> c = {1, 2, 3, 4};
  std::cout << (a >= c) << std::endl; // Output: 1
  return 0;
}
